import{_ as o,V as i,W as t,Z as a,$ as l,a0 as d,a1 as e,Y as r,F as n}from"./framework-b1bd8911.js";const s={},p=r("<p>imagic-plugin 是 QuickMedia 系列中负责图片编辑的工具包，底层基于 ImageMagick（通过 im4java 进行命令行调用），上层做了 Builder 模式的链式封装，把 ImageMagick 原本冗长的 <code>convert</code> 命令行参数，收敛成一行一意、可读性很高的 Java 代码。</p><p>它的定位是&quot;图片编辑器&quot;：旋转、裁剪、缩放这类基本编辑操作，原生 Java（BufferedImage + Graphics2D）也能做，但会遇到 jpg 变红、精度丢失、颜色失真等老问题；ImageMagick 是 C++ 实现的专业图片处理工具，稳定性和图片质量都更有保障，缺点是需要在本机安装环境。imagic-plugin 的价值就在于：帮你把 ImageMagick 的能力用最低的成本接入 Java 项目。</p><p>当前已支持的能力清单：</p><ol><li>图片旋转：<code>rotate</code></li><li>图片裁剪：<code>crop</code></li><li>图片缩放/压缩：<code>scale</code>（支持指定宽高、按比例缩放、指定图片精度 quality、强制拉伸）</li><li>上下翻转：<code>flip</code></li><li>左右镜像：<code>flop</code></li><li>添加水印：<code>water</code>（水印图支持 classpath 资源、网络图片、输入流）</li><li>添加边框：<code>board</code>（可指定边框宽高与填充色）</li><li>复合操作：以上操作支持链式叠加，一次调用按顺序完成多个编辑动作</li></ol><p>输入输出都很灵活：输入支持 classpath 资源、远程图片（URI）、二进制流；输出支持文件、<code>InputStream</code>、<code>byte[]</code>、<code>BufferedImage</code> 等多种形态。</p><p><strong>系列文章</strong></p>",6),g=a("code",null,"ImgWrapper",-1);function m(u,_){const c=n("RouterLink");return i(),t("div",null,[p,a("ul",null,[a("li",null,[l(c,{to:"/git/quick-media/imagic/01.%E5%9F%BA%E4%BA%8EImageMagic%E5%AE%9E%E7%8E%B0%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91%E5%99%A8.html"},{default:d(()=>[e("1.基于ImageMagic实现图片编辑器")]),_:1}),e("：ImageMagick 环境安装、依赖引入、"),g,e(" 全 API 使用说明与复合操作实战")])])])}const f=o(s,[["render",m],["__file","index.html.vue"]]);export{f as default};
